script.setup:
// Paper.js computes boolean operations (unite, intersect, subtract, exclude) between moving
// vector shapes every frame; the scene flattens the result to points and fills it with WebGL.
const mod = await ctx.utils.import("https://esm.sh/paper@0.12.18");
const paper = mod.default ?? mod;
// A project without a visible view: Paper.js only does geometry here.
paper.setup(new paper.Size(1000, 1000));
const gl = ctx.gl;
gl.getExtension("EXT_color_buffer_float");
const flat = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_position; layout(location=1) in vec4 a_color;
uniform vec2 u_px; out vec4 v_color;
void main(){ v_color = a_color; gl_Position = vec4(a_position / u_px * 2.0 - 1.0, 0.0, 1.0); }`, `#version 300 es
precision highp float; in vec4 v_color; out vec4 outColor;
void main(){ outColor = v_color; }`);
const vao = gl.createVertexArray(), vbo = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 24, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 4, gl.FLOAT, false, 24, 8);
gl.bindVertexArray(null);
const kit = {
  // Draws a flat (x, y, r, g, b, a) triangle list.
  draw(arr) {
    if (!arr.length) return;
    gl.useProgram(flat);
    ctx.utils.setUniforms(flat, { u_px: ctx.resolution });
    gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(arr), gl.DYNAMIC_DRAW);
    gl.drawArrays(gl.TRIANGLES, 0, arr.length / 6);
    gl.bindVertexArray(null);
  },
  // Signed triangle fan: inside a closed ring the triangles add up to ±c, outside they cancel.
  // Summed with additive blending, this fills any polygon (holes, self-overlaps) exactly.
  fan(ring, c, out) {
    const x0 = ring[0], y0 = ring[1];
    for (let i = 2; i + 3 < ring.length; i += 2) {
      const s = Math.sign((ring[i] - x0) * (ring[i + 3] - y0) - (ring[i + 1] - y0) * (ring[i + 2] - x0));
      if (!s) continue;
      out.push(x0, y0, c[0] * s, c[1] * s, c[2] * s, c[3] * s,
        ring[i], ring[i + 1], c[0] * s, c[1] * s, c[2] * s, c[3] * s,
        ring[i + 2], ring[i + 3], c[0] * s, c[1] * s, c[2] * s, c[3] * s);
    }
  },
  // Thick polyline as quads (WebGL lines are 1 px); square ends overlap at the joints.
  line(pts, closed, width, c, out) {
    const n = pts.length / 2, hw = width / 2;
    for (let i = 0; i < (closed ? n : n - 1); i++) {
      const j = (i + 1) % n;
      const ax = pts[i * 2], ay = pts[i * 2 + 1], bx = pts[j * 2], by = pts[j * 2 + 1];
      const len = Math.hypot(bx - ax, by - ay);
      if (len < 1e-6) continue;
      const dx = (bx - ax) / len * hw, dy = (by - ay) / len * hw;
      const p = [ax - dx - dy, ay - dy + dx, ax - dx + dy, ay - dy - dx, bx + dx + dy, by + dy - dx, bx + dx - dy, by + dy + dx];
      for (const k of [0, 1, 2, 0, 2, 3]) out.push(p[k * 2], p[k * 2 + 1], c[0], c[1], c[2], c[3]);
    }
  },
  // Disc made of triangles.
  dot(x, y, r, c, out, seg = 16) {
    for (let i = 0; i < seg; i++) {
      const a0 = i / seg * 6.2832, a1 = (i + 1) / seg * 6.2832;
      out.push(x, y, ...c, x + Math.cos(a0) * r, y + Math.sin(a0) * r, ...c, x + Math.cos(a1) * r, y + Math.sin(a1) * r, ...c);
    }
  },
  acc: null,
  // Renders signed fans additively into a half-float target at up to 2x the canvas size
  // (sampling it back with linear filtering smooths the edges). Returns the texture.
  accumulate(arr) {
    const [w, h] = ctx.resolution, k = Math.min(2, 4096 / Math.max(w, h));
    const tw = Math.round(w * k), th = Math.round(h * k);
    if (!kit.acc) kit.acc = ctx.utils.createPingPong(tw, th, { internalFormat: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT });
    else if (kit.acc.width !== tw || kit.acc.height !== th) kit.acc.resize(tw, th);
    const t = kit.acc.read();
    gl.bindFramebuffer(gl.FRAMEBUFFER, t.framebuffer); gl.viewport(0, 0, tw, th);
    gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT);
    gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
    kit.draw(arr);
    gl.disable(gl.BLEND);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null); gl.viewport(0, 0, w, h);
    return t.texture;
  },
};
const s = ctx.state;
Object.assign(s, { paper, kit, moved: false, bx: null, by: null });
s.show = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_fill; uniform vec2 u_resolution; uniform vec3 u_colorA; uniform vec3 u_colorB; uniform vec3 u_bg;
float cover(vec2 uv){ return clamp(abs(texture(u_fill, uv).r), 0.0, 1.0); }
void main(){
  vec2 px = 1.0 / u_resolution;
  // Soft shadow: a blurred, offset copy of the coverage.
  float sh = 0.0;
  for (int i = -2; i <= 2; i++) for (int j = -2; j <= 2; j++) sh += cover(v_uv + vec2(-6.0 + float(i) * 5.0, 10.0 + float(j) * 5.0) * px);
  sh /= 25.0;
  vec2 q = (v_uv - 0.5) * vec2(u_resolution.x / u_resolution.y, 1.0);
  vec3 bg = u_bg * (1.0 - 0.35 * dot(q, q));
  bg *= 1.0 - 0.35 * sh;
  float a = cover(v_uv);
  vec3 c = mix(u_colorA, u_colorB, clamp(v_uv.y * 1.2 - 0.1 + 0.2 * sin(v_uv.x * 4.0), 0.0, 1.0));
  outColor = vec4(mix(bg, c, a), 1.0);
}`);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, kit = s.kit, P = s.paper;
const [w, h] = ctx.resolution, t = ctx.time * u.u_speed, R = h * 0.34;
const cx = w / 2, cy = h / 2;
// Shape A: a turning star with rounded points.
const a = new P.Path.Star({ center: [cx - R * 0.25, cy], points: u.u_points, radius1: R * 0.55, radius2: R, insert: false });
a.smooth({ type: "geometric", factor: u.u_round });
a.rotate(t * 20);
// Shape B: a ring (circle with a hole) that orbits, or follows the pointer once it has moved.
const [mx, my] = ctx.mouse;
s.moved ||= mx !== 0.5 || my !== 0.5;
const tx = s.moved ? mx * w : cx + Math.cos(t * 0.8) * R * 0.9, ty = s.moved ? (1 - my) * h : cy + Math.sin(t * 1.1) * R * 0.6;
s.bx = s.bx === null ? tx : s.bx + (tx - s.bx) * 0.2; s.by = s.by === null ? ty : s.by + (ty - s.by) * 0.2;
const outer = new P.Path.Circle({ center: [s.bx, s.by], radius: R * 0.62, insert: false });
const hole = new P.Path.Circle({ center: [s.bx, s.by], radius: R * 0.3, insert: false });
const b = outer.subtract(hole, { insert: false });
const ops = ["unite", "intersect", "subtract", "exclude"];
const result = a[ops[u.u_op]](b, { insert: false });
// Flatten each sub-path into points (Paper.js turns its curves into short line segments).
const ringsOf = (item) => {
  const rings = [], paths = item.children ? item.children : [item];
  for (const p of paths) {
    const f = p.clone({ insert: false });
    f.flatten(Math.max(1, h * 0.002));
    const pts = [];
    for (const seg of f.segments) pts.push(seg.point.x, seg.point.y);
    if (pts.length >= 6) rings.push(pts);
  }
  return rings;
};
const fills = [], lines = [];
const lw = Math.max(1, h * 0.003);
for (const ring of ringsOf(result)) {
  kit.fan(ring, [1, 0, 0, 0], fills);
  kit.line(ring, true, lw * 1.4, [0.08, 0.08, 0.12, 0.9], lines);
}
// The inputs, as thin outlines.
for (const ring of [...ringsOf(a), ...ringsOf(b)]) kit.line(ring, true, lw * 0.6, [0.1, 0.1, 0.15, 0.35], lines);
const tex = kit.accumulate(fills);
gl.useProgram(s.show);
ctx.utils.bindTexture(s.show, "u_fill", tex, 0);
ctx.utils.drawFullscreen(s.show);
gl.enable(gl.BLEND); gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
kit.draw(lines);
gl.disable(gl.BLEND);
ctx.publish("result area", Math.round(Math.abs(result.area) / (h * h) * 1000) / 1000);
ctx.publish("operation", ops[u.u_op]);
